package com.forensic.docintel.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.forensic.docintel.model.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class InvestigationService {
    private final DocumentAnalyzer analyzer; private final ObjectMapper mapper;
    @Value("${app.storage:./data}") private String storage;
    private final Map<UUID,Investigation> sessions=new ConcurrentHashMap<>();
    public InvestigationService(DocumentAnalyzer analyzer,ObjectMapper mapper){this.analyzer=analyzer;this.mapper=mapper;}
    public Investigation create(List<MultipartFile> files) throws Exception {
        if(files==null||files.isEmpty()) throw new IllegalArgumentException("Upload at least one document.");
        if(files.size()>10) throw new IllegalArgumentException("An investigation can contain at most 10 documents.");
        UUID id=UUID.randomUUID(); Path dir=Path.of(storage).resolve(id.toString()); Files.createDirectories(dir);
        List<DocumentRecord> docs=new ArrayList<>(); for(MultipartFile f:files) docs.add(analyzer.analyze(f,dir));
        List<Finding> findings=correlate(docs); String summary=findings.isEmpty()?"No rule-based discrepancy was found in the extracted fields. This is not a certification of authenticity.":findings.size()+" review item(s) require human examination. Findings are indicators, not a determination of fraud.";
        String markdown=dossier(id,docs,findings,summary); Investigation inv=new Investigation(id,Instant.now(),"complete",docs,findings,summary,markdown); sessions.put(id,inv);
        Files.writeString(dir.resolve("dossier.md"),markdown); appendAudit(dir,id,docs,findings); return inv;
    }
    public Investigation get(UUID id){Investigation x=sessions.get(id);if(x==null)throw new NoSuchElementException("Investigation not found in this application session.");return x;}
    public Path source(UUID inv,String doc){Path p=Path.of(storage).resolve(inv.toString()).normalize(); if(!p.startsWith(Path.of(storage).toAbsolutePath().normalize())&&!p.startsWith(Path.of(storage).normalize()))throw new IllegalArgumentException("Invalid path");try(var files=Files.list(p)){return files.filter(f->f.getFileName().toString().startsWith(doc+"-")).findFirst().orElseThrow();}catch(Exception e){throw new NoSuchElementException("Source document not found.");}}
    private List<Finding> correlate(List<DocumentRecord> docs){List<Finding> out=new ArrayList<>(); Set<String> fields=new LinkedHashSet<>();docs.forEach(d->fields.addAll(d.fields().keySet()));
        for(String field:fields){if(Set.of("document_date","signature").contains(field))continue;Map<String,List<Map.Entry<DocumentRecord,DocumentRecord.FieldValue>>> vals=new LinkedHashMap<>();for(var d:docs){var f=d.fields().get(field);if(f!=null)vals.computeIfAbsent(norm(f.value()),k->new ArrayList<>()).add(Map.entry(d,f));}
            if(vals.size()>1){List<String> dids=docs.stream().filter(d->d.fields().containsKey(field)).map(DocumentRecord::id).toList();List<String> eids=docs.stream().filter(d->d.fields().containsKey(field)).flatMap(d->d.fields().get(field).evidenceIds().stream()).distinct().toList();String display=field.replace('_',' ');String parts=docs.stream().filter(d->d.fields().containsKey(field)).map(d->d.fileName()+" = “"+d.fields().get(field).value()+"”").reduce((a,b)->a+"; "+b).orElse("");out.add(new Finding("F-"+(out.size()+1),"cross-document discrepancy","medium","requires review","Conflicting "+display,parts+". The values may reflect a legitimate change, extraction error, or inconsistent source record; verify against authoritative evidence.",0.78,dids,eids,"Compare the original source fields and confirm which record is current."));}
        }
        for(var d:docs){for(String required:List.of("applicant_name")){if(!d.fields().containsKey(required))out.add(new Finding("F-"+(out.size()+1),"missing information","low","requires review","Applicant name not extracted", "No applicant name was extracted from "+d.fileName()+". The field may be absent, labeled differently, or missed by OCR.",0.63,List.of(d.id()),List.of(),"Inspect the source document and correct extraction if needed."));}
            for(var obs:d.observations()) if(obs.startsWith("No usable text"))out.add(new Finding("F-"+(out.size()+1),"processing limitation","low","observation","OCR fallback used",obs,0.96,List.of(d.id()),d.evidence().stream().limit(1).map(DocumentRecord.EvidenceLine::id).toList(),"Review OCR output against the original image."));
            for(var obs:d.observations()) if(obs.startsWith("Potential visual style outlier")){java.util.regex.Matcher m=java.util.regex.Pattern.compile("page (\\d+), line (\\d+)").matcher(obs);int page=1,line=1;if(m.find()){page=Integer.parseInt(m.group(1));line=Integer.parseInt(m.group(2));}final int evidencePage=page,evidenceLine=line;List<String> visualEvidence=d.evidence().stream().filter(e->e.page()==evidencePage&&e.line()==evidenceLine).map(DocumentRecord.EvidenceLine::id).toList();out.add(new Finding("F-"+(out.size()+1),"visual style observation","low","observation","Font style differs from page baseline",obs,0.72,List.of(d.id()),visualEvidence,"Compare this source line with surrounding lines and the issuing template; a style change alone does not establish alteration."));}
        }
        return out;
    }
    private String norm(String s){return s.toLowerCase(Locale.ROOT).replaceAll("[^\\p{Alnum}]","");}
    private String dossier(UUID id,List<DocumentRecord> docs,List<Finding> findings,String summary){StringBuilder b=new StringBuilder("# Investigation dossier\n\n");b.append("**Investigation:** `").append(id).append("`  \n**Generated:** ").append(Instant.now()).append("  \n**Status:** Complete for automated prototype analysis  \n**Decision boundary:** Findings are indicators for human review. No fraud determination is made.\n\n");
        b.append("## 7.1 Document overview\n\n| Document | Type | Source | Status | SHA-256 |\n|---|---|---|---|---|\n");for(var d:docs)b.append("| ").append(d.fileName()).append(" | ").append(d.documentType()).append(" | ").append(d.source()).append(" | ").append(d.processingStatus()).append(" | `").append(d.sha256()).append("` |\n");
        b.append("\n## 7.2 Extracted information\n\n");for(var d:docs){b.append("### ").append(d.fileName()).append("\n\n");if(d.fields().isEmpty())b.append("No supported fields extracted.\n\n");else{b.append("| Field | Value | Confidence | Evidence location |\n|---|---|---:|---|\n");for(var e:d.fields().entrySet())b.append("| ").append(e.getKey()).append(" | ").append(e.getValue().value().replace("|","\\|")).append(" | ").append(String.format(Locale.ROOT,"%.0f%%",e.getValue().confidence()*100)).append(" | ").append(e.getValue().evidenceIds()).append(" |\n");b.append('\n');}}
        b.append("## 7.3 Contextual analysis\n\n");if(findings.isEmpty())b.append("No cross-document conflicts were found in supported extracted fields.\n\n");else for(var f:findings)b.append("- **").append(f.title()).append("** — ").append(f.explanation()).append("\n");
        b.append("\n## 7.4 Visual forensic findings\n\n");for(var d:docs){b.append("- **").append(d.fileName()).append("** — ").append(d.extractionMethod()).append("; ").append(d.pageCount()).append(" page(s). ");b.append(d.observations().isEmpty()?"No automated image manipulation finding was generated. Pixel-level tamper localization, font provenance, signature authenticity, and alteration confirmation are unsupported.":String.join(" ",d.observations()));b.append('\n');}b.append("\n## 7.5 Evidence and traceability\n\n");for(var d:docs){b.append("### ").append(d.fileName()).append(" (`").append(d.sha256()).append("`)\n\n");for(var e:d.evidence())b.append("- `").append(e.id()).append("` — ").append(e.sourceLocator()).append(" — “").append(e.text().replace("|","\\|")).append("” (").append(e.method()).append(")\n");b.append('\n');}
        b.append("## 7.6 Investigation summary\n\n").append(summary).append("\n\n");if(findings.isEmpty())b.append("### Areas requiring additional verification\n\n- Confirm identity and source authenticity through the issuing authority.\n- Review all original pages and any low-confidence OCR.\n\n");else for(var f:findings)b.append("- **").append(f.title()).append(" (confidence ").append(String.format(Locale.ROOT,"%.0f%%",f.confidence()*100)).append(")**: ").append(f.recommendedAction()).append(" Evidence IDs: ").append(f.evidenceIds()).append(".\n");
        b.append("\n### Limitations\n\nRule-based extraction supports a narrow set of English labels. OCR confidence is a recognition score, not truth confidence. PDF text-layer line locations are approximate; OCR image evidence uses normalized page bounding boxes. The prototype does not verify signatures, detect font manipulation reliably, or determine authenticity. Human review is required.\n\n### Chain of custody notes\n\nOriginal uploads are stored unchanged for the life of the local application data directory; SHA-256 is recorded at ingestion. A local append-only JSONL event file records the analysis event. This prototype is not a certified evidence preservation system.\n");return b.toString();}
    private void appendAudit(Path dir,UUID id,List<DocumentRecord> docs,List<Finding> fs)throws Exception{Map<String,Object> event=new LinkedHashMap<>();event.put("event","investigation.completed");event.put("investigationId",id);event.put("at",Instant.now());event.put("documentHashes",docs.stream().map(DocumentRecord::sha256).toList());event.put("findingIds",fs.stream().map(Finding::id).toList());Files.writeString(dir.resolve("audit.jsonl"),mapper.writeValueAsString(event)+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}
}
